sys_ux_data_broker_transform.script:
function transform(input) {
    var propertyName = 'sam.foundation.current.procurement_form_questions';
    var propertyValue = gs.getProperty(propertyName);
    var transformedData = { questions: [] };

    if (propertyValue) {
        try {
            var questionsData = JSON.parse(propertyValue);
            gs.log("Raw property value: " + propertyValue);

            for (var key in questionsData) {
                if (questionsData.hasOwnProperty(key)) {
                    var questionObj = {
                        id: key,
                        question: questionsData[key].question,
                        dependent_inputs: questionsData[key].dependent_inputs || []
                    };
                    transformedData.questions.push(questionObj);
                }
            }

            gs.log("Transformed Questions: " + JSON.stringify(transformedData));

        } catch (e) {
            gs.log("Error parsing sys_property: " + e.message);
            return { error: "Invalid JSON in sys_property" };
        }
    } else {
        gs.log("Sys_property is not set or empty.");
        return { error: "No data found in sys_property" };
    }

    return transformedData;
}
